const out=[];
for(const [i,item] of $input.all().entries()){
 const m=item.json.message;
 if(!m || m.chat?.type!=='private' || m.from?.is_bot || m.chat?.id==null || m.message_id==null) continue;
 const texto=typeof m.text==='string'?m.text.trim():'';
 out.push({json:{chatId:String(m.chat.id),messageId:String(m.message_id),texto,tipo:texto?'texto':'sin_texto'},pairedItem:{item:i}});
}
return out;

const base=$('Preparar mensaje').item.json;
let d;
try {
 const raw=$json.output;
 d=typeof raw==='object' && raw!==null ? raw : JSON.parse(String(raw).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim());
} catch {}
const valid=!!(d && ['responder','pedir_aclaracion','recomendar_asesor'].includes(d.accion)
 && typeof d.respuesta==='string' && d.respuesta.trim() && d.respuesta.length<=1200
 && typeof d.motivo==='string' && Array.isArray(d.fuentes) && d.fuentes.length<=5
 && d.fuentes.every(f=>typeof f==='string' && f.length<=200));
if(!valid) d={accion:'recomendar_asesor',respuesta:'No pude verificar la información automáticamente. Podés consultar https://pimesa.com.ar o comunicarte con un asesor de PIME.',motivo:'Error del agente o salida inválida',fuentes:[]};
const noTexto=base.tipo==='sin_texto';
return [{json:{chatId:base.chatId,messageId:base.messageId,
 accion:noTexto?'pedir_aclaracion':d.accion,
 respuesta:noTexto?'Por ahora puedo procesar mensajes de texto. ¿Podés escribir tu consulta?':d.respuesta.trim(),
 motivo:d.motivo.slice(0,500),fuentes:noTexto?[]:d.fuentes,valid}}];

const body=$json.body;
const fail=error=>[{json:{ok:false,httpStatus:400,error}}];
if(!body || typeof body!=='object' || Array.isArray(body)) return fail('Se requiere un objeto JSON con documento_id, titulo y contenido.');
const {documento_id,titulo,contenido}=body;
if(typeof documento_id!=='string' || !/^[a-zA-Z0-9_-]{3,100}$/.test(documento_id)) return fail('documento_id debe tener entre 3 y 100 caracteres: letras, números, guion o guion bajo.');
if(typeof titulo!=='string' || titulo.trim().length<3 || titulo.trim().length>200) return fail('titulo debe tener entre 3 y 200 caracteres.');
if(typeof contenido!=='string' || contenido.trim().length<80 || contenido.length>30000) return fail('contenido debe tener entre 80 y 30000 caracteres.');
if(body.fuente!==undefined && (typeof body.fuente!=='string' || body.fuente.length>500)) return fail('fuente debe ser texto de hasta 500 caracteres.');
if(body.version!==undefined && (typeof body.version!=='string' || body.version.length>50)) return fail('version debe ser texto de hasta 50 caracteres.');
return [{json:{ok:true,documento_id,titulo:titulo.trim(),contenido:contenido.trim(),fuente:body.fuente||'documento_administrado',version:body.version||'1',fecha_carga:new Date().toISOString()}}];

const items=$input.all();
const errorItem=items.find(i=>i.json && i.json.error);
const base=$('Validar documento').first().json;
if(errorItem || !items.length || items.every(i=>!i.json || Object.keys(i.json).length===0)) {
 return [{json:{ok:false,httpStatus:502,error:'No se pudo completar la carga. Revisar Ollama, dimensiones y Supabase en Executions. Puede haber inserciones parciales: comprobar la tabla antes de reintentar.',documento_id:base.documento_id}}];
}
return [{json:{ok:true,httpStatus:200,documento_id:base.documento_id,titulo:base.titulo,resultados_devuelto:items.length,mensaje:'La operación de inserción terminó sin error reportado. Verificar filas y embeddings en Supabase.'}}];
